@Component("bOMItem-handler")
@ProcessingGroup("bOMItem-processing-group")
public class BOMItemEventHandler {
	
	// core constructor
	BOMItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBOMItemEvent
     */
    @EventHandler
    public void handle( CreateBOMItemEvent event) {
        entityManager.persist(new BOMItem(event.getBOMItemId(), event.getLineNumber(), event.getQuantity(), event.getScrapPercent(), event.getBom(), event.getComponent()));
    }

    /*
     * @param	event UpdateBOMItemEvent
     */
    @EventHandler
    public BOMItem handle( UpdateBOMItemEvent event) {
    	entityManager.merge(new BOMItem(event.getBOMItemId(), event.getLineNumber(), event.getQuantity(), event.getScrapPercent(), event.getBom(), event.getComponent()));
    }
    
    /*
     * @param	event DeleteBOMItemEvent
     */
    @EventHandler
    public void on( DeleteBOMItemEvent event) {
    	BOMItem entity = new BOMItem();
   
    	// ------------------------------------------
    	// apply the BOMItemId
    	// ------------------------------------------
    	entity.setBOMItemId( event.getBOMItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BOMItemRepository bOMItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BOMItemEventHandler.class.getName());

}
